  "Alternates restrained punch-ins at measured phrase changes. Each picture clip needs a transcript with word timing. Position stays as authored; this does not track a face or camera.": "מחליף בין התקרבויות מתונות בנקודות שינוי מדודות של משפטים. לכל קטע חזותי נדרש תמלול עם תזמון מילים. המיקום נשאר כפי שנקבע; אין כאן מעקב אחר פנים או מצלמה.",
