  "Choose the destination": "בחירת יעד הפרסום",
  "Choose the output": "בחירת התוצאה",
  "Choose the platform and complete its authorization flow. Check the account name when you return to the studio.": "יש לבחור פלטפורמה ולהשלים את תהליך ההרשאה שלה. יש לבדוק את שם החשבון כשחוזרים לסטודיו.",
  "Choose the scale.": "יש לבחור את קנה המידה.",
