  "Choose the source": "בחירת המקור",
  "Choose the voice that fits your story. Your generated audio stays in this brand’s Library.": "יש לבחור קול שמתאים לסיפור שלך. השמע שנוצר נשאר בספרייה של המותג הזה.",
  "Choose what would count as a real win.": "יש לבחור מה ייחשב הצלחה אמיתית.",
