  "Clear rules for renewals, withdrawal, service problems, and credits.": "כללים ברורים לחידושים, ביטול עסקה, תקלות שירות וקרדיטים.",
  "Clear selection": "ביטול הבחירה",
  "Clear transitions": "ניקוי מעברים",
  "Clear white subtitles with a dark outline.": "כתוביות לבנות ברורות עם קו מתאר כהה.",
  "Clearer contrast and color.": "ניגודיות וצבע ברורים יותר.",
  "Click Record or type a chord. Enter Escape to assign Esc. Remove every shortcut to disable an action.": "יש ללחוץ על הקלטה או להקליד צירוף מקשים. יש להזין Escape כדי להקצות Esc. הסרת כל הקיצורים משביתה את הפעולה.",
  "Click a clip to select it and move the playhead. Use its adjustments to refine it, drag its edges to trim, and use Split or Duplicate for another version. Higher numbered video tracks appear in front of lower ones.": "לחיצה על קטע בוחרת אותו ומזיזה את סמן הניגון. אפשר לדייק אותו בהגדרות, לגרור את קצותיו לחיתוך ולהשתמש בפיצול או שכפול לגרסה אחרת. ערוצי וידאו בעלי מספר גבוה מופיעים לפני בעלי מספר נמוך.",
  "Click to preview · drag to place on the timeline": "לחיצה לתצוגה מקדימה · גרירה להצבה בציר הזמן",
  "Clicks": "לחיצות",
  "Clip continuity": "המשכיות הקטע",
