  "Clip entrance & exit": "כניסה ויציאה של הקטע",
  "Clip fades": "עמעומי הקטע",
  "Clip name": "שם הקטע",
  "Clip settings, canvas and the end of your edit.": "הגדרות הקטע, הקנבס וסוף העריכה שלך.",
  "Clip snapping": "הצמדת קטעים",
  "Clip start": "תחילת הקטע",
  "Clipboard access is blocked. Select the prompt preview and copy it manually.": "הגישה ללוח ההעתקה חסומה. יש לבחור את התצוגה המקדימה של ההנחיה ולהעתיק אותה ידנית.",
  "Clipboard access is blocked. Select the script and copy it manually.": "הגישה ללוח ההעתקה חסומה. יש לבחור את התסריט ולהעתיק אותו ידנית.",
  "Clipboard access is blocked. Select the script text and copy it manually.": "הגישה ללוח ההעתקה חסומה. יש לבחור את טקסט התסריט ולהעתיק אותו ידנית.",
  "Clipboard access was blocked. Select the script and copy it manually.": "הגישה ללוח ההעתקה נחסמה. יש לבחור את התסריט ולהעתיק אותו ידנית.",
