  "Compare brand allowances": "השוואת מכסות מותג",
  "Compare plans and review the final terms in checkout.": "אפשר להשוות תוכניות ולבדוק את התנאים הסופיים בתשלום.",
  "Compare posts and publication history, then choose one improvement for the next piece. Use Goals or Weekly Review to keep that action visible.": "אפשר להשוות פוסטים והיסטוריית פרסום ואז לבחור שיפור אחד לפריט הבא. יעדים או סקירה שבועית יעזרו להשאיר את הפעולה גלויה.",
  "Compare the displayed credits, connected-account limits, and billing period. Choose the option you need, then review the final checkout amount and terms.": "יש להשוות את הקרדיטים, מגבלות החשבונות המחוברים ותקופת החיוב המוצגים. יש לבחור אפשרות מתאימה ואז לבדוק את סכום התשלום והתנאים הסופיים.",
  "Compiled direction": "הנחיה מאוחדת",
  "Compiled prompt": "פרומפט מאוחד",
  "Complete any verification shown after signup. If you already have an account, use Sign in to keep your existing work together.": "יש להשלים כל אימות שמופיע אחרי ההרשמה. אם כבר יש לך חשבון, אפשר להשתמש בכניסה כדי לשמור את העבודה הקיימת יחד.",
  "Complete the password reset opened from your email link.": "יש להשלים את איפוס הסיסמה שנפתח מקישור הדוא״ל שלך.",
  "Completed AI actions · UTC dates · failed and pending jobs excluded.": "פעולות בינה מלאכותית שהושלמו · תאריכי UTC · משימות שנכשלו או ממתינות אינן נכללות.",
  "Completing sign-in": "השלמת כניסה",
  "Compose or schedule": "כתיבה או תזמון",
  "Configuration checks do not verify provider balances or live payments. Updated": "בדיקות הגדרות אינן מאמתות יתרות ספקים או תשלומים חיים. עודכן",
