  "Confirm you may use every source file, reference frame, identifiable person, voice, brand, and third-party work.": "יש לאשר שמותר לך להשתמש בכל קובץ מקור, פריים לייחוס, אדם מזוהה, קול, מותג ויצירה של צד שלישי.",
  "Confirmed published · 7d": "פרסום אושר · 7 ימים",
  "Confirming your payment and credits. This page checks automatically; delayed payment methods may take longer.": "אימות התשלום והקרדיטים שלך. העמוד בודק אוטומטית; אמצעי תשלום מושהים עשויים להימשך יותר זמן.",
