  "Hi — I’m REELassati Support. Tell me what you’re trying to do and what happened. I’ll troubleshoot it step by step, or prepare a complete support ticket when human help is the better route.": "שלום — אני תמיכת REELassati. אפשר לספר מה ניסית לעשות ומה קרה. אעזור לפתור צעד אחר צעד או להכין פנייה מלאה לתמיכה כשעזרה אנושית מתאימה יותר.",
