  "I agree to the ": "אני מסכים/ה ל- ",
  "I am authorized to download and use this video.": "יש לי הרשאה להוריד ולהשתמש בסרטון הזה.",
  "I can't access my account": "אין לי גישה לחשבון",
  "I hold documented consent or another verified legal basis.": "יש בידי הסכמה מתועדת או בסיס משפטי אחר שאומת.",
  "I may download this reference and submit it to the AI analysis provider.": "מותר לי להוריד את הרפרנס הזה ולהעביר אותו לספק ניתוח הבינה המלאכותית.",
  "I may use the prompt, brands, references, faces and voices in this generation.": "מותר לי להשתמש בהנחיה, במותגים, ברפרנסים, בפנים ובקולות ביצירה הזו.",
  "I may use this prompt, its brands, and its likenesses.": "מותר לי להשתמש בהנחיה הזו, במותגים ובדמויות שבה.",
  "I may use this text and voice. If the voice identifies a real person, I have documented consent or another verified legal basis.": "מותר לי להשתמש בטקסט ובקול הזה. אם הקול מזהה אדם אמיתי, יש בידי הסכמה מתועדת או בסיס משפטי אחר שאומת.",
  "I need to open a support ticket": "פתיחת פנייה לתמיכה",
  "Idea — improvement request": "רעיון — בקשת שיפור",
  "Ideas": "רעיונות",
  "Identity and contact details for the REELassati service provider.": "פרטי זהות ויצירת קשר של ספק השירות REELassati.",
  "If a feature is not accessible, tell us the page, action, device, and assistive technology. We prioritise barriers affecting sign-in, purchase, creation, and account management: ": "אם תכונה אינה נגישה, יש לציין את העמוד, הפעולה, המכשיר והטכנולוגיה המסייעת. אנו מתעדפים חסמים שמשפיעים על כניסה, רכישה, יצירה וניהול חשבון: ",
  "If a ticket is prepared, review its subject, description, and contact details before sending it. A prepared ticket is sent only after you submit it.": "אם הוכנה פנייה, יש לבדוק את הנושא, התיאור ופרטי הקשר לפני השליחה. פנייה מוכנה נשלחת רק אחרי הגשתה.",
  "If content appears to misuse your likeness, voice, work, or personal information, contact the human support channel with the relevant page, asset, or publication reference.": "אם נראה שתוכן עושה שימוש לרעה בדמותך, בקולך, ביצירתך או במידע האישי שלך, יש לפנות לערוץ התמיכה האנושית עם הפניה לעמוד, לנכס או לפרסום הרלוונטי.",
  "If the page reports a failure, return to Sign in and try the same account method again. Include the error when contacting support.": "אם העמוד מדווח על כשל, יש לחזור לכניסה ולנסות שוב באותה שיטת גישה לחשבון. יש לכלול את השגיאה בפנייה לתמיכה.",
  "If you buy as a consumer in the EEA or a country with equivalent rights, a statutory withdrawal period may apply, commonly 14 days for distance contracts. If you request immediate service, you may owe a proportionate amount for service already supplied. Loss of withdrawal rights for digital content occurs only when all legal requirements, including express consent and acknowledgement, are met. To exercise a right, send an unambiguous statement with your account email and purchase to ": "ברכישה כצרכן באזור הכלכלי האירופי או במדינה עם זכויות מקבילות, ייתכן שחלה תקופת ביטול חוקית, בדרך כלל 14 ימים בחוזים מרחוק. בבקשת שירות מיידי ייתכן חיוב יחסי על שירות שכבר ניתן. אובדן זכות הביטול לתוכן דיגיטלי מתרחש רק כשכל הדרישות המשפטיות מולאו, לרבות הסכמה מפורשת ואישור ידיעה. למימוש זכות יש לשלוח הצהרה חד-משמעית עם דוא״ל החשבון ופרטי הרכישה אל ",
  "If you received a code, enter it in the claim section and read the confirmation or eligibility message.": "אם התקבל קוד, יש להזין אותו בסעיף הבקשה ולקרוא את הודעת האישור או הזכאות.",
  "If you used a social sign-in provider, use that provider’s access flow. Contact support if the account remains inaccessible.": "אם השתמשת בספק כניסה חברתי, יש להשתמש בתהליך הגישה שלו. אם החשבון נשאר לא נגיש, יש לפנות לתמיכה.",
