  "Import a static GLB, compose a pose, and save a transparent image for your timeline.": "ייבוא GLB סטטי, עיצוב תנוחה ושמירת תמונה שקופה לציר הזמן שלך.",
  "Import private reference · no AI credits": "ייבוא רפרנס פרטי · ללא קרדיטים של בינה מלאכותית",
  "Import subtitle file": "ייבוא קובץ כתוביות",
