  "Impressions": "חשיפות",
  "In Studio profile, review your details and timezone. Save changes before leaving the section.": "בפרופיל הסטודיו יש לבדוק את הפרטים ואזור הזמן שלך. יש לשמור שינויים לפני היציאה מהסעיף.",
  "In speech synthesis, filter voices and languages, read their tags, and play a sample. Generate from the final text after reviewing the credit cost, then use the audio file in your edit.": "בסינתזת דיבור אפשר לסנן קולות ושפות, לקרוא את התגיות ולהשמיע דוגמה. יש ליצור מהטקסט הסופי אחרי בדיקת עלות הקרדיטים ואז להשתמש בקובץ השמע בעריכה.",
  "Include AI assistance label": "הוספת תווית סיוע בבינה מלאכותית",
  "Include it": "לכלול",
  "Include it · {{credits}} cr": "לכלול · {{credits}} קרדיטים",
  "Include selected · skip rest": "לכלול את הנבחרים · לדלג על היתר",
  "Include the project or file name and any error message. Keep passwords and API keys out of the report.": "יש לכלול את שם הפרויקט או הקובץ וכל הודעת שגיאה. אין לכלול סיסמאות או מפתחות API בדוח.",
  "Include your specific example, evidence, and intended takeaway. Describe the tone you want and any facts or promises the script must avoid.": "יש לכלול דוגמה מסוימת, ראיות והמסר הרצוי. יש לתאר את הטון הרצוי וכל עובדה או הבטחה שעל התסריט להימנע ממנה.",
  "Included credits are allocated monthly and do not roll over; annual plans release them monthly.": "הקרדיטים הכלולים מוקצים מדי חודש ואינם נצברים; תוכניות שנתיות משחררות אותם מדי חודש.",
  "Included · queued": "כלול · בתור",
  "Includes the 5-credit planning step and any paid actions. Approval mode never raises this limit.": "כולל את שלב התכנון של 5 קרדיטים וכל פעולה בתשלום. מצב האישור לעולם אינו מגדיל את המגבלה הזו.",
  "Indonesian": "אינדונזית",
