  "Inspect available provenance": "בדיקת מידע מקור זמין",
  "Inspect hook, pacing, and concrete edit opportunities.": "בדיקת פתיחה מושכת, קצב והזדמנויות עריכה קונקרטיות.",
  "Inspect pasted text or a media file for a REELassati provenance record and supported machine-readable signals. Inspection input is not retained. A missing signal means “not verified,” not “human-made.”": "בדיקת טקסט שהודבק או קובץ מדיה לאיתור רשומת מקור של REELassati וסימנים נתמכים הקריאים למכונה. הקלט לבדיקה אינו נשמר. סימן חסר פירושו ״לא אומת״, ולא ״נוצר בידי אדם״.",
