  "Legal operator": "מפעיל משפטי",
  "Legal remedies for a non-conforming digital service remain available. Failed generations automatically release reserved credits. For duplicate charges, missing access, undelivered credits, or persistent problems, contact support; we will verify payment and usage records and apply a refund, credit restoration, or another appropriate remedy.": "הסעדים המשפטיים לשירות דיגיטלי שאינו תואם נשארים זמינים. יצירות שנכשלו משחררות אוטומטית קרדיטים שהוקצו. בחיובים כפולים, גישה חסרה, קרדיטים שלא נמסרו או בעיות מתמשכות יש לפנות לתמיכה; נבדוק רשומות תשלום ושימוש וניישם החזר, שחזור קרדיטים או פתרון מתאים אחר.",
  "Legitimate interests: security, abuse prevention, reliability, legal claims, and strictly necessary operational measurement, balanced against user rights.": "אינטרסים לגיטימיים: אבטחה, מניעת שימוש לרעה, אמינות, תביעות משפטיות ומדידה תפעולית הכרחית בלבד, באיזון מול זכויות המשתמש.",
