  "Open Graphics → Motion kits for a brand reveal, speaker introduction, chapter, quote, statistic or closing card. Edit the text, accent and duration; the brand reveal can use a logo from Library. Add at the playhead, then refine the grouped layers on the timeline. Undo removes the whole insertion. These native templates use no AI credits.": "אפשר לפתוח גרפיקה ← ערכות תנועה לחשיפת מותג, הצגת דובר, פרק, ציטוט, נתון או כרטיס סיום. אפשר לערוך את הטקסט, ההדגשה והמשך; חשיפת המותג יכולה להשתמש בלוגו מהספרייה. יש להוסיף בסמן הניגון ואז לדייק את השכבות המקובצות בציר הזמן. ביטול מסיר את כל ההוספה. התבניות המובנות האלה אינן צורכות קרדיטים של בינה מלאכותית.",
