  "Open a preset to read its direction and editable prompt. A preset supplies structure; your subject and source files make the result specific.": "אפשר לפתוח תבנית כדי לקרוא את ההכוונה וההנחיה הניתנת לעריכה שלה. תבנית מספקת מבנה; הנושא וקובצי המקור שלך הופכים את התוצאה למסוימת.",
  "Open a publication in Publisher to change its draft or schedule. A calendar event plans work; it does not publish a post. Check the displayed workspace timezone.": "אפשר לפתוח פרסום בכלי הפרסום כדי לשנות את הטיוטה או התזמון. אירוע ביומן מתכנן עבודה; הוא אינו מפרסם פוסט. יש לבדוק את אזור הזמן המוצג של סביבת העבודה.",
  "Open a result and review its source link, date, and available evidence. A hypothesis is a proposed test, not proof that a format will perform.": "יש לפתוח תוצאה ולבדוק את קישור המקור, התאריך והראיות הזמינות. השערה היא ניסוי מוצע, לא הוכחה שפורמט יצליח.",
