  "REELassati Support": "תמיכת REELassati",
  "REELassati accessibility": "נגישות REELassati",
  "REELassati combines manual production tools with reviewable AI assistance. This page identifies where AI is used, the information sent when you invoke it, and the controls that remain with you.": "REELassati משלבת כלי הפקה ידניים עם סיוע בבינה מלאכותית הניתן לבחינה. העמוד הזה מזהה היכן משתמשים בבינה מלאכותית, איזה מידע נשלח בהפעלתה ואילו אמצעי שליטה נשארים אצלך.",
  "REELassati credits": "קרדיטים של REELassati",
  "REELassati designs interfaces around WCAG 2.2 AA principles: semantic structure, accessible names, visible focus, contrast, keyboard navigation, reduced motion, and feedback that does not rely on colour alone. This is an operating target, not a claim of complete certified conformance.": "REELassati מעצבת ממשקים לפי עקרונות WCAG 2.2 AA: מבנה סמנטי, שמות נגישים, מיקוד נראה, ניגודיות, ניווט במקלדת, תנועה מופחתת ומשוב שאינו מסתמך רק על צבע. זהו יעד תפעולי, לא הצהרה על התאמה מלאה ומוסמכת.",
  "REELassati home": "עמוד הבית של REELassati",
  "REELassati is intended for human-directed creative and marketing production. It is not designed to make consequential decisions about people, infer sensitive traits, or present deceptive synthetic media as authentic.": "REELassati מיועדת להפקה יצירתית ושיווקית בהכוונה אנושית. היא אינה מיועדת לקבל החלטות בעלות השלכות משמעותיות על אנשים, להסיק תכונות רגישות או להציג מדיה סינתטית מטעה כאותנטית.",
  "REELassati is intended for users aged 18 or older. Material changes to this notice will be communicated appropriately before they take effect.": "REELassati מיועדת למשתמשים בגיל 18 ומעלה. שינויים מהותיים בהודעה זו יימסרו כראוי לפני כניסתם לתוקף.",
  "REELassati provides tools to plan, create, edit, analyse, organise, and publish short-form content. You must be at least 18 and able to enter a contract. Anyone using the service for an organisation confirms authority to bind it.": "REELassati מספקת כלים לתכנון, יצירה, עריכה, ניתוח, ארגון ופרסום תוכן קצר. נדרש גיל 18 לפחות וכשירות להתקשר בחוזה. מי שמשתמש בשירות בשם ארגון מאשר שיש לו סמכות לחייב אותו.",
  "REELassati updates this feed internally; no action or credits are required from you.": "REELassati מעדכנת את הפיד פנימית; לא נדרשים ממך פעולה או קרדיטים.",
  "Range end": "סוף הטווח",
