  "Review available performance evidence and publication history.": "בדיקת ראיות ביצועים זמינות והיסטוריית פרסום.",
  "Review before applying": "בדיקה לפני החלה",
  "Review client reports, set priority, and move work through the product queue.": "בדיקת דוחות לקוחות, הגדרת עדיפות וקידום העבודה בתור המוצר.",
  "Review each account’s status and reconnect when requested. Available platforms and account limits are shown in the interface.": "יש לבדוק את מצב כל חשבון ולהתחבר מחדש לפי הצורך. הפלטפורמות הזמינות ומגבלות החשבונות מוצגות בממשק.",
  "Review or export one of your open edits before starting another. Open edits: {{count}}": "יש לבדוק או לייצא אחת מהעריכות הפתוחות לפני התחלת נוספת. עריכות פתוחות: {{count}}",
  "Review recent studio activity and choose the next useful action.": "סקירת הפעילות האחרונה בסטודיו ובחירת הפעולה המועילה הבאה.",
  "Review the account terms": "בדיקת תנאי החשבון",
  "Review the credit cost before starting. Check the job status and the finished clip before using it; a generated file can be reused from Library.": "יש לבדוק את עלות הקרדיטים לפני ההתחלה. יש לבדוק את מצב המשימה ואת הקטע המוגמר לפני השימוש; אפשר להשתמש שוב בקובץ שנוצר מהספרייה.",
  "Review the current value and update it with real results. Edit a goal when its scope changes rather than leaving an outdated target.": "יש לבדוק את הערך הנוכחי ולעדכן אותו בתוצאות אמיתיות. כשההיקף משתנה, יש לערוך את היעד במקום להשאיר מטרה מיושנת.",
  "Review the generated hook, body, and ending. Check factual claims, then save the script or continue refining it.": "יש לבדוק את הפתיחה המושכת, הגוף והסיום שנוצרו. יש לבדוק טענות עובדתיות ואז לשמור את התסריט או להמשיך לדייק אותו.",
  "Review the next action": "בדיקת הפעולה הבאה",
  "Review the product’s content rules and practical review steps.": "בדיקת כללי התוכן של המוצר ושלבי הבדיקה המעשיים.",
  "Review the relevant sections and the date shown on this page. Follow linked documents when you need the full context.": "יש לקרוא את הסעיפים הרלוונטיים ואת התאריך המוצג בעמוד. יש לעבור למסמכים המקושרים כשנדרש ההקשר המלא.",
  "Review the reported match method and available record. Recorded origin, an embedded mark, and a verified file match provide different evidence.": "יש לבדוק את שיטת ההתאמה שדווחה ואת הרשומה הזמינה. מקור מתועד, סימן מוטמע והתאמת קובץ מאומתת מספקים ראיות שונות.",
  "Review the systems": "בדיקת המערכות",
  "Review the terms that apply to your account and use of the service.": "בדיקת התנאים החלים על החשבון ועל השימוש שלך בשירות.",
  "Review the whole edit before export. Your current device renders the video: keep the page open, and try 720p or a shorter edit if memory is limited. Download-only avoids a Library upload; Library saving makes the result available for later publication. AI media needs Library saving to finalize its source marking. Rendering uses no AI credits. AI generation, hosting and storage still have costs and allowances.": "יש לבדוק את כל העריכה לפני הייצוא. המכשיר הנוכחי שלך מפיק את הווידאו: יש להשאיר את העמוד פתוח ולנסות 720p או עריכה קצרה יותר כשהזיכרון מוגבל. הורדה בלבד מונעת העלאה לספרייה; שמירה בספרייה מאפשרת פרסום בהמשך. מדיה מבינה מלאכותית דורשת שמירה בספרייה לסיום סימון המקור. ההפקה אינה צורכת קרדיטים של בינה מלאכותית. ליצירת בינה מלאכותית, אירוח ואחסון עדיין יש עלויות ומכסות.",
  "Review tracked path ·": "בדיקת מסלול המעקב ·",
  "Review your plan, available credits, usage, and checkout options.": "בדיקת התוכנית, הקרדיטים הזמינים, השימוש ואפשרויות התשלום שלך.",
  "Reviewable decisions": "החלטות הניתנות לבדיקה",
  "Reviewable edit suggestions that a person can accept, reject, or ignore.": "הצעות עריכה שאדם יכול לבדוק, לקבל, לדחות או להתעלם מהן.",
  "Reviews a supplied video for editorial hook, pacing, and time-based suggestions. Scores are rubric assessments, not predicted views.": "סקירת סרטון שסופק לפתיחה מושכת, קצב והצעות לפי זמן. הציונים הם הערכות לפי מחוון, לא תחזיות צפיות.",
  "Revolutions": "סיבובים",
  "Reward history": "היסטוריית תגמולים",
  "Right": "ימין",
  "Rights": "זכויות",
