  "Ripple delete across all tracks": "מחיקה וסגירת רווחים בכל הערוצים",
  "Ripple delete removes the selected time intervals from every unlocked track and closes the gaps. Undo restores the complete edit.": "מחיקה זו מסירה את טווחי הזמן שנבחרו מכל ערוץ שאינו נעול וסוגרת את הרווחים. ביטול משחזר את כל העריכה.",
