  "Sign in or create an account to work with your own files. Pricing explains the plans; Contact opens support.": "אפשר להיכנס או ליצור חשבון כדי לעבוד עם הקבצים שלך. עמוד המחירים מסביר את התוכניות; יצירת קשר פותחת תמיכה.",
