  "Sign up": "הרשמה",
  "Sign-in sessions, security, abuse prevention, theme, language, selected workspace, interface state, and the privacy preference are needed to provide requested features. They may use cookies, localStorage, or sessionStorage and are not used for advertising.": "הפעלות כניסה, אבטחה, מניעת שימוש לרעה, ערכת נושא, שפה, סביבת עבודה נבחרת, מצב הממשק והעדפת פרטיות נדרשים למתן תכונות שהתבקשו. הם עשויים להשתמש בקובצי cookie, ב-localStorage או ב-sessionStorage ואינם משמשים לפרסום.",
  "Sign-in, security, balance, preferences, and requested features.": "כניסה, אבטחה, יתרה, העדפות ותכונות שהתבקשו.",
