  "Tax identifier": "מזהה מס",
  "Tell Reel the result you want, such as “Add captions and a title for the first three seconds.” Use + or drop a reference into the chat for context. You can name a time range in your request.": "אפשר לומר ל-Reel את התוצאה הרצויה, למשל ״הוסף כתוביות וכותרת בשלוש השניות הראשונות״. אפשר להשתמש ב-+ או לגרור רפרנס לצ׳אט להוספת הקשר. אפשר לציין טווח זמן בבקשה.",
  "Tell Reel what you want to change. Attach a reference, point to a moment, or start with an idea.": "אפשר לומר ל-Reel מה ברצונך לשנות. אפשר לצרף רפרנס, להצביע על רגע או להתחיל מרעיון.",
  "Tell the support assistant what you are trying to do, which page you used, and the exact error. It can answer product questions and help prepare the next step.": "יש לומר לעוזר התמיכה מה ניסית לעשות, באיזה עמוד השתמשת ומה השגיאה המדויקת. הוא יכול לענות על שאלות מוצר ולעזור להכין את השלב הבא.",
  "Ten real presets turn your subject into more precise video direction: camera, light, movement, audio, continuity, and exclusions. No preset guarantees performance.": "עשר תבניות אמיתיות הופכות את הנושא שלך להכוונת וידאו מדויקת יותר: מצלמה, אור, תנועה, שמע, המשכיות והחרגות. שום תבנית אינה מבטיחה ביצועים.",
