  "Updating…": "עדכון…",
  "Upload a real audio asset, transcribe it by asset ID, shape the transcript into a short-form script, or synthesize a production-ready voice track.": "אפשר להעלות נכס שמע אמיתי, לתמלל אותו לפי מזהה נכס, לעצב את התמליל לתסריט קצר או לסנתז ערוץ קול מוכן להפקה.",
  "Upload an audio file or choose a saved source. Transcribe it, then review names and wording before using the text.": "יש להעלות קובץ שמע או לבחור מקור שמור. יש לתמלל אותו ואז לבדוק שמות וניסוחים לפני שימוש בטקסט.",
  "Upload footage or create a project to start your activity history.": "אפשר להעלות חומרי גלם או ליצור פרויקט כדי להתחיל את היסטוריית הפעילות שלך.",
