  "Upload, trim, split, caption, review AI changes, and version your short.": "העלאה, חיתוך, פיצול, הוספת כתוביות, בדיקת שינויי בינה מלאכותית ושמירת גרסאות לסרטון הקצר שלך.",
  "Uploaded source": "מקור שהועלה",
  "Uploaded to Library. Drag a thumbnail onto the timeline to place it.": "הועלה לספרייה. אפשר לגרור תמונה ממוזערת לציר הזמן כדי להציב אותה.",
  "Uploading {{progress}}%": "העלאה {{progress}}%",
  "Upper captions that leave the lower frame clear.": "כתוביות עליונות שמשאירות את תחתית הפריים נקייה.",
  "Urgent": "דחוף",
  "Usage could not be loaded. Try Refresh.": "לא ניתן לטעון נתוני שימוש. אפשר לנסות רענון.",
  "Use Forgot password to request a reset for an email-and-password account. Follow the message sent to that email address.": "יש להשתמש בשכחת סיסמה לבקשת איפוס לחשבון עם דוא״ל וסיסמה. יש לפעול לפי ההודעה שנשלחה לכתובת הזו.",
  "Use a PNG, JPEG or WebP image up to 20 MB.": "יש להשתמש בתמונת PNG, JPEG או WebP בגודל של עד 20 מ״ב.",
  "Use a file in your workflow": "שימוש בקובץ בתהליך העבודה שלך",
  "Use a name and a valid range within the video, without overlapping another section.": "יש להשתמש בשם ובטווח תקף בתוך הווידאו, ללא חפיפה לחלק אחר.",
  "Use a public link. Upload the file if the source requires sign-in.": "יש להשתמש בקישור ציבורי. אם המקור דורש כניסה, יש להעלות את הקובץ.",
  "Use a source-linked trend above or add your own observation.": "אפשר להשתמש במגמה עם מקור מקושר למעלה או להוסיף תצפית משלך.",
  "Use a transparent PNG or WebP for a logo without a background.": "יש להשתמש ב-PNG או WebP שקוף ללוגו ללא רקע.",
  "Use an available sign-in provider or complete the name, email, and password fields. Use an email address you can access.": "אפשר להשתמש בספק כניסה זמין או להשלים את שדות השם, הדוא״ל והסיסמה. יש להשתמש בכתובת שיש לך גישה אליה.",
  "Use as starting point": "שימוש כנקודת התחלה",
  "Use at least 8 characters. Your new password replaces the old one immediately.": "יש להשתמש בלפחות 8 תווים. הסיסמה החדשה מחליפה מיד את הקודמת.",
  "Use call to action {{number}}": "שימוש בקריאה לפעולה {{number}}",
  "Use connected accounts": "שימוש בחשבונות מחוברים",
  "Use dark theme": "שימוש בערכת נושא כהה",
  "Use every Nth onset": "שימוש בכל התחלת צליל N",
  "Use hook {{number}}": "שימוש בפתיחה מושכת {{number}}",
  "Use in Edit": "שימוש בעריכה",
  "Use light theme": "שימוש בערכת נושא בהירה",
  "Use playhead · source": "שימוש בסמן הניגון · מקור",
  "Use search and type filters to narrow the library. Preview the asset to check its content before reusing it.": "אפשר לצמצם את הספרייה באמצעות חיפוש ומסנני סוג. יש להציג את הנכס כדי לבדוק את תוכנו לפני שימוש חוזר.",
  "Use the Studio to develop scripts, edit media, analyze creative structure, generate supporting shots or narration, and prepare approved content for distribution.": "אפשר להשתמש בסטודיו לפיתוח תסריטים, עריכת מדיה, ניתוח מבנה יצירתי, יצירת שוטים תומכים או קריינות והכנת תוכן מאושר להפצה.",
  "Use the available account and period controls to compare the same scope. Check when the information was last synced.": "יש להשתמש בבקרות החשבון והתקופה הזמינות כדי להשוות אותו היקף. יש לבדוק מתי המידע סונכרן לאחרונה.",
  "Use the billing-management control for the options available to your subscription. If checkout does not open, read the on-page error or contact support with the selected plan.": "יש להשתמש בניהול החיוב לאפשרויות הזמינות למנוי שלך. אם התשלום אינו נפתח, יש לקרוא את השגיאה בעמוד או לפנות לתמיכה עם התוכנית שנבחרה.",
  "Use the brand switcher in the sidebar before working. Brand DNA holds the audience, voice, and visual direction for that brand.": "לפני עבודה יש להשתמש במחליף המותגים בסרגל הצד. DNA של המותג מכיל את הקהל, הקול והכיוון החזותי שלו.",
  "Use the contact details in the document for a request. Include the section or account issue your question concerns.": "יש להשתמש בפרטי הקשר שבמסמך להגשת בקשה. יש לכלול את הסעיף או בעיית החשבון שאליהם נוגעת השאלה.",
  "Use the creation and review steps on this page before distributing the finished content.": "יש להשתמש בשלבי היצירה והבדיקה בעמוד לפני הפצת התוכן המוגמר.",
  "Use the email address associated with your account and submit the request.": "יש להשתמש בכתובת הדוא״ל של החשבון ולהגיש את הבקשה.",
  "Use the exact source and measurable signal.": "יש להשתמש במקור המדויק ובסימן מדיד.",
  "Use the linked policies and official sources for more detail, and Contact for a question about a specific workflow.": "למידע נוסף אפשר להשתמש במדיניות המקושרת ובמקורות רשמיים, ולשאלה על תהליך עבודה מסוים — ביצירת קשר.",
  "Use the matching tab, then paste the text or select the original file you want to check.": "יש להשתמש בלשונית המתאימה ואז להדביק טקסט או לבחור את הקובץ המקורי לבדיקה.",
  "Use the quick actions to write a script, create media, analyze footage, or open the editing studio. The sidebar keeps these tools available.": "אפשר להשתמש בפעולות המהירות לכתיבת תסריט, יצירת מדיה, ניתוח חומר גלם או פתיחת סטודיו העריכה. הכלים זמינים בסרגל הצד.",
  "Use the reported error": "שימוש בשגיאה שדווחה",
  "Use the reporting or contact links for a specific issue and provide enough context to identify the content.": "יש להשתמש בקישורי דיווח או יצירת קשר לבעיה מסוימת ולספק מספיק הקשר לזיהוי התוכן.",
  "Use the reset link": "שימוש בקישור האיפוס",
  "Use the suggested replies": "שימוש בתשובות המוצעות",
  "Use the transcript as material for a short-form script. Give the script a clear audience and outcome rather than keeping every spoken detour.": "יש להשתמש בתמליל כחומר לתסריט קצר. יש להגדיר קהל ותוצאה ברורים במקום לשמר כל סטייה בדיבור.",
  "Use this call to action": "שימוש בקריאה הזו לפעולה",
  "Use this opening": "שימוש בפתיחה הזו",
  "Use wider spacing to stay within 48 cut points.": "יש להשתמש במרווחים רחבים יותר כדי להישאר במסגרת 48 נקודות חיתוך.",
