  "Uses existing media and measured speech. No AI credits. Apply creates one saved revision; Undo restores the previous edit.": "משתמש במדיה קיימת ובדיבור מדוד. ללא קרדיטים של בינה מלאכותית. החלה יוצרת גרסה שמורה אחת; ביטול משחזר את העריכה הקודמת.",
  "Uses measured word timings from transcription. Imported subtitles or edited lines without word timings display the whole phrase.": "משתמש בתזמון מילים שנמדד בתמלול. כתוביות שיובאו או שורות שנערכו ללא תזמון מילים מציגות את כל המשפט.",
  "Uses unused footage around the cut. Speech timing and total edit length stay fixed. Other overlapping video layers must be resolved first.": "משתמש בחומר שלא נוצל סביב החיתוך. תזמון הדיבור ואורך העריכה הכולל נשארים קבועים. יש לפתור קודם שכבות וידאו חופפות אחרות.",
