  "Walkthroughs show example workflows. Presets provide a starting direction that you can adapt to your own subject.": "הדרכות מציגות דוגמאות לתהליכי עבודה. תבניות מספקות כיוון התחלתי שאפשר להתאים לנושא שלך.",
