  "We may change or suspend features for security, law, maintenance, or provider changes. We do not promise marketing results, virality, or uninterrupted availability. Nothing excludes liability that law does not allow us to exclude or mandatory consumer remedies. Otherwise, total liability relating to the service is limited to the amount paid in the 12 months before the event.": "אנו עשויים לשנות או להשעות תכונות לצורכי אבטחה, חוק, תחזוקה או שינויים אצל ספקים. איננו מבטיחים תוצאות שיווקיות, ויראליות או זמינות רציפה. אין בכך החרגת אחריות שהחוק אינו מתיר להחריג או סעדים מחייבים לצרכן. במקרים אחרים, האחריות הכוללת הקשורה לשירות מוגבלת לסכום ששולם ב-12 החודשים שלפני האירוע.",
  "We may suspend an account for violations, security risk, non-payment, or legal duties, using proportionate measures. Italian law applies without depriving consumers of mandatory protections in their country of residence or mandatory courts. For support or complaints: ": "אנו עשויים להשעות חשבון בשל הפרות, סיכון אבטחה, אי-תשלום או חובות משפטיות, תוך שימוש באמצעים מידתיים. הדין האיטלקי חל בלי לשלול הגנות צרכן מחייבות במדינת המגורים או סמכות שיפוט מחייבת. לתמיכה או תלונות: ",
  "We sent a secure confirmation link to": "שלחנו קישור אישור מאובטח אל",
  "We'll send you a reset link": "נשלח לך קישור לאיפוס",
