  "When reporting an issue, include the failing action and its error alongside the relevant status. Review the AI information available here when learning how the tools behave.": "בדיווח על בעיה יש לכלול את הפעולה שנכשלה ואת השגיאה שלה לצד המצב הרלוונטי. אפשר לקרוא את מידע הבינה המלאכותית הזמין כאן כדי להבין את התנהגות הכלים.",
  "Where applicable, you may request access, correction, deletion, restriction, portability, or objection; withdraw consent without affecting prior processing; and complain to the Italian Data Protection Authority or another competent authority. Account settings include data export and a deletion-request path.": "כשהדבר חל, אפשר לבקש גישה, תיקון, מחיקה, הגבלה, ניידות או התנגדות; לבטל הסכמה בלי להשפיע על עיבוד קודם; ולהגיש תלונה לרשות האיטלקית להגנת מידע או לרשות מוסמכת אחרת. הגדרות החשבון כוללות ייצוא נתונים ומסלול לבקשת מחיקה.",
