  "Your account or brand changed. Start again in the intended workspace.": "החשבון או המותג השתנו. יש להתחיל שוב בסביבת העבודה הרצויה.",
  "Your account or brand changed. Start again with the current Library image.": "החשבון או המותג השתנו. יש להתחיל שוב עם תמונת הספרייה הנוכחית.",
